import { IEnvironmentAware } from "../environment-aware";
import * as constructs from "constructs";
/**
 * Indicates that this resource can be referenced as a Registry.
 *
 * @stability experimental
 */
export interface IRegistryRef extends constructs.IConstruct, IEnvironmentAware {
    /**
     * A reference to a Registry resource.
     */
    readonly registryRef: RegistryReference;
}
/**
 * A reference to a Registry resource.
 *
 * @struct
 * @stability external
 */
export interface RegistryReference {
    /**
     * The RegistryArn of the Registry resource.
     */
    readonly registryArn: string;
}
/**
 * Indicates that this resource can be referenced as a RegistryRecord.
 *
 * @stability experimental
 */
export interface IRegistryRecordRef extends constructs.IConstruct, IEnvironmentAware {
    /**
     * A reference to a RegistryRecord resource.
     */
    readonly registryRecordRef: RegistryRecordReference;
}
/**
 * A reference to a RegistryRecord resource.
 *
 * @struct
 * @stability external
 */
export interface RegistryRecordReference {
    /**
     * The RecordArn of the RegistryRecord resource.
     */
    readonly recordArn: string;
}
